dashboard.definition:
{
	"title": "ABAP Network & Security",
	"description": "",
	"inputs": {
		"input_global_trp": {
			"options": {
				"defaultValue": "-30d@d,now",
				"token": "global_time"
			},
			"title": "Global Time Range",
			"type": "input.timerange"
		},
		"input_nav_dropdown": {
			"type": "input.dropdown",
			"title": "Navigate to Dashboard",
			"options": {
				"items": [
					{"label": "Overview", "value": "logserv_overview"},
					{"label": "DNS Analytics", "value": "logserv_dns_analytics"},
					{"label": "HANA Audit", "value": "logserv_hana_audit"},
					{"label": "HANA Trace", "value": "logserv_hana_trace"},
					{"label": "Web Dispatcher", "value": "logserv_web_dispatcher"},
					{"label": "Host Details", "value": "logserv_host_details"},
					{"label": "ABAP Operations", "value": "logserv_abap_operations"},
					{"label": "SAP Services", "value": "logserv_sap_services"},
					{"label": "Cloud Connector", "value": "logserv_cloud_connector"},
					{"label": "Linux", "value": "logserv_linux"},
					{"label": "Windows", "value": "logserv_windows"},
					{"label": "Proxy", "value": "logserv_proxy"},
					{"label": "Environment Health", "value": "logserv_environment_health"}
				],
				"token": "nav_target"
			}
		}
	},
	"defaults": {
		"dataSources": {
			"ds.search": {
				"options": {
					"queryParameters": {
						"earliest": "$global_time.earliest$",
						"latest": "$global_time.latest$"
					}
				}
			}
		}
	},
	"visualizations": {
		"viz_kpi_total": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_total"},
			"title": "Total Events",
			"options": {
				"majorValue": "> primary | seriesByName('total') | lastPoint()",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			}
		},
		"viz_kpi_errors": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_errors"},
			"title": "ICM Errors",
			"options": {
				"majorValue": "> primary | seriesByName('errors') | lastPoint()",
				"majorColor": "#dc4e41",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			}
		},
		"viz_kpi_gw_errors": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_kpi_gw_errors"},
			"title": "Gateway Errors",
			"options": {
				"majorValue": "> primary | seriesByName('gw_errors') | lastPoint()",
				"majorColor": "#f1813f",
				"backgroundColor": "transparent",
				"sparklineDisplay": "off",
				"trendDisplay": "off"
			}
		},
		"viz_volume_by_type": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_volume_by_type"},
			"title": "Event Volume by Sourcetype",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			}
		},
		"viz_icm_status": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_icm_status"},
			"title": "ICM Status Codes Over Time",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColorsByField": {
					"2xx": "#4fa484",
					"3xx": "#0877a6",
					"4xx": "#dc4e41",
					"5xx": "#f1813f"
				}
			}
		},
		"viz_icm_peers": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_icm_peers"},
			"title": "ICM Peer Connections",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_icm_request_types": {
			"type": "splunk.pie",
			"dataSources": {"primary": "ds_icm_request_types"},
			"title": "ICM Request Types",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"showDonutHole": true,
				"backgroundColor": "transparent"
			}
		},
		"viz_gw_hosts": {
			"type": "splunk.table",
			"dataSources": {"primary": "ds_gw_hosts"},
			"title": "Gateway Remote Hosts",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)",
					"headerBackgroundColor": "> backgroundColor | setColorChannel(tableHeaderBackgroundColorConfig)",
					"rowColors": "> rowBackgroundColors | maxContrast(tableRowColorMaxContrast)",
					"headerColor": "> headerBackgroundColor | maxContrast(tableRowColorMaxContrast)"
				}
			}
		},
		"viz_gw_errors_timeline": {
			"type": "splunk.line",
			"dataSources": {"primary": "ds_gw_errors_timeline"},
			"title": "Gateway Errors Over Time",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide",
				"seriesColors": ["#dc4e41"]
			}
		},
		"viz_sid_instance": {
			"type": "splunk.column",
			"dataSources": {"primary": "ds_sid_instance"},
			"title": "Activity by SID / Instance",
			"showProgressBar": false,
			"showLastUpdated": false,
			"options": {
				"backgroundColor": "transparent",
				"stackMode": "stacked",
				"xAxisTitleVisibility": "hide",
				"yAxisTitleVisibility": "hide"
			}
		},
		"viz_rect_top_left": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_top_mid": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_top_right": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_mid_left": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_mid_right": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_bot_left": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_rect_bot_right": {
			"type": "splunk.rectangle",
			"options": {"fillColor": "transparent", "rx": 3, "strokeColor": "#0877a6"}
		},
		"viz_nav_go": {
			"type": "splunk.singlevalue",
			"dataSources": {"primary": "ds_nav_go"},
			"options": {
				"majorValue": "> primary | seriesByName('label') | lastPoint()",
				"backgroundColor": "#0877a6",
				"majorColor": "#ffffff",
				"sparklineDisplay": "off",
				"trendDisplay": "off",
				"majorFontSize": 14
			},
			"eventHandlers": [
				{
					"type": "drilldown.customUrl",
					"options": {
						"url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
						"newTab": false
					}
				}
			]
		}
	},
	"dataSources": {
		"ds_kpi_total": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:abap:audit\", \"sap:abap:gateway\", \"sap:abap:icm\") | stats count as total"
			}
		},
		"ds_kpi_errors": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:icm\" icm_is_error=1 | stats count as errors"
			}
		},
		"ds_kpi_gw_errors": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:gateway\" gw_error_detail=* gw_error_detail!=\"\" | stats count as gw_errors"
			}
		},
		"ds_volume_by_type": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:abap:audit\", \"sap:abap:gateway\", \"sap:abap:icm\") | timechart span=1d count by sourcetype"
			}
		},
		"ds_icm_status": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:icm\" icm_status_code=* | eval status_cat=case(icm_status_code>=200 AND icm_status_code<300, \"2xx\", icm_status_code>=300 AND icm_status_code<400, \"3xx\", icm_status_code>=400 AND icm_status_code<500, \"4xx\", icm_status_code>=500, \"5xx\", 1=1, \"Other\") | timechart span=1d count by status_cat"
			}
		},
		"ds_icm_peers": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:icm\" icm_peer_ip=* | stats count as Requests dc(icm_transaction_id) as Transactions values(icm_protocol) as Protocols by icm_peer_ip | sort -Requests | head 20 | rename icm_peer_ip as \"Peer IP\""
			}
		},
		"ds_icm_request_types": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:icm\" icm_request_type=* | stats count by icm_request_type | sort -count"
			}
		},
		"ds_gw_hosts": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:gateway\" | stats count as Events values(gw_service) as Services latest(gw_error_detail) as \"Last Error\" by gw_remote_host gw_function | sort -Events | head 20 | rename gw_remote_host as \"Remote Host\" gw_function as \"Function\""
			}
		},
		"ds_gw_errors_timeline": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype=\"sap:abap:gateway\" gw_error_detail=* gw_error_detail!=\"\" | timechart span=1d count as \"Gateway Errors\""
			}
		},
		"ds_sid_instance": {
			"type": "ds.search",
			"options": {
				"query": "`sap_logserv_idx_macro` sourcetype IN (\"sap:abap:audit\", \"sap:abap:gateway\", \"sap:abap:icm\") | stats count by sap_sid sap_instance | sort -count | head 20"
			}
		},
		"ds_nav_go": {
			"type": "ds.search",
			"options": {
				"query": "| makeresults | eval label=\"Go >\"",
				"queryParameters": {
					"earliest": "-1m",
					"latest": "now"
				}
			}
		}
	},
	"layout": {
		"globalInputs": ["input_global_trp", "input_nav_dropdown"],
		"layoutDefinitions": {
			"layout_1": {
				"options": {
					"height": 1200,
					"width": 1920
				},
				"structure": [
					{"item": "viz_nav_go", "type": "block", "position": {"x": 1790, "y": 0, "w": 120, "h": 35}},
					{"item": "viz_kpi_total", "type": "block", "position": {"x": 10, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_errors", "type": "block", "position": {"x": 320, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_kpi_gw_errors", "type": "block", "position": {"x": 630, "y": 45, "w": 300, "h": 90}},
					{"item": "viz_rect_top_left", "type": "block", "position": {"x": 10, "y": 150, "w": 940, "h": 340}},
					{"item": "viz_volume_by_type", "type": "block", "position": {"x": 20, "y": 155, "w": 920, "h": 330}},
					{"item": "viz_rect_top_right", "type": "block", "position": {"x": 960, "y": 150, "w": 950, "h": 340}},
					{"item": "viz_icm_status", "type": "block", "position": {"x": 970, "y": 155, "w": 930, "h": 330}},
					{"item": "viz_rect_mid_left", "type": "block", "position": {"x": 10, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_icm_peers", "type": "block", "position": {"x": 20, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_mid_right", "type": "block", "position": {"x": 640, "y": 505, "w": 640, "h": 340}},
					{"item": "viz_gw_hosts", "type": "block", "position": {"x": 650, "y": 510, "w": 620, "h": 330}},
					{"item": "viz_rect_top_mid", "type": "block", "position": {"x": 1290, "y": 505, "w": 620, "h": 340}},
					{"item": "viz_icm_request_types", "type": "block", "position": {"x": 1300, "y": 510, "w": 600, "h": 330}},
					{"item": "viz_rect_bot_left", "type": "block", "position": {"x": 10, "y": 860, "w": 950, "h": 330}},
					{"item": "viz_gw_errors_timeline", "type": "block", "position": {"x": 20, "y": 865, "w": 930, "h": 320}},
					{"item": "viz_rect_bot_right", "type": "block", "position": {"x": 970, "y": 860, "w": 940, "h": 330}},
					{"item": "viz_sid_instance", "type": "block", "position": {"x": 980, "y": 865, "w": 920, "h": 320}}
				],
				"type": "absolute"
			}
		},
		"options": {},
		"tabs": {
			"items": [{"label": "New tab", "layoutId": "layout_1"}]
		}
	}
}
